using System;
using System.Runtime.InteropServices;

// Test stackalloc with native-sized integers
Span<nint> signedSpan = stackalloc nint[5];
Span<nuint> unsignedSpan = stackalloc nuint[5];

for (int i = 0; i < signedSpan.Length; i++)
{
    signedSpan[i] = i * 10;
    unsignedSpan[i] = (nuint)(i * 100);
}

Console.WriteLine($"nint size:  {sizeof(nint)} bytes ({sizeof(nint) * 8}-bit)");
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes ({sizeof(nuint) * 8}-bit)");
Console.WriteLine();

Console.WriteLine("Span<nint> contents:");
foreach (var val in signedSpan)
    Console.Write($"  {val}");
Console.WriteLine();

Console.WriteLine("Span<nuint> contents:");
foreach (var val in unsignedSpan)
    Console.Write($"  {val}");
Console.WriteLine();

